import { graphql } from '@/gql'

// Every operation the console uses. Types are generated by `pnpm codegen`
// from x/admin/graph/schema.graphqls and planning.graphqls.

export const EntityPartsFragment = graphql(`
  fragment EntityParts on Entity {
    name source datasource schema kind description primaryKey uniqueKeys params affects allowCascade tenantPolicy legacyAccess
    mcp { dmlTools customTool trustedProcedure }
    fields { name alias description mask exclude }
    relationships { name target cardinality joinOn }
  }
`)

export const GrantPartsFragment = graphql(`
  fragment GrantParts on Grant { entity actions fieldsRestricted readFields writeFields rows }
`)

export const DatasourcePartsFragment = graphql(`
  fragment DatasourceParts on Datasource {
    name driver dsn readAfterWrite
    connections { name dsn role pooler }
    routing { read write execute }
  }
`)

export const RevisionPartsFragment = graphql(`
  fragment RevisionParts on Revision { id parent state contentHash author comment createdAt publishedAt }
`)

export const WorkspaceQuery = graphql(`
  query Workspace($id: ID!) {
    published { id }
    revision(id: $id) {
      ...RevisionParts
      config {
        datasources { ...DatasourceParts }
        entities { ...EntityParts }
        roles { name description members grants { ...GrantParts } }
        users { name description roles subject disabled hasToken grants { ...GrantParts } }
        settings
      }
    }
  }
`)

export const StatusQuery = graphql(`
  query Status {
    serverStatus { appliedRevision watching pending { id restartRequired error } }
    published { ...RevisionParts }
  }
`)

export const ConfigSchemaQuery = graphql(`
  query ConfigSchema { configSchema }
`)

export const PublishedQuery = graphql(`
  query Published { published { ...RevisionParts } }
`)

export const RevisionsQuery = graphql(`
  query Revisions($limit: Int) { revisions(limit: $limit) { ...RevisionParts } }
`)

export const RevisionHashQuery = graphql(`
  query RevisionHash($id: ID!) {
    revision(id: $id) { id contentHash config { datasources { ...DatasourceParts } } }
  }
`)

export const RevisionYamlQuery = graphql(`
  query RevisionYaml($id: ID!) { revision(id: $id) { id yaml } }
`)

// Scanning goes schema by schema: list the schemas, then scan them. A scan
// runs in the background on the server (start it, then poll); the server
// keeps each schema's last scan in its catalog until the next one.
export const ImportTablePartsFragment = graphql(`
  fragment ImportTableParts on ImportTable {
    schema table description status configuredAs
    columns { name type nullable description primaryKey }
    keys { name columns primary reason }
    indexes { name method parts unique primary where }
    foreignKeys { name columns refSchema refTable refColumns onDelete onUpdate }
    sideEffects
    candidate { ...EntityParts }
  }
`)

// The schema list of a datasource with what was scanned of each schema; the
// tables are read from the catalog (CatalogQuery), a page at a time.
export const SchemaListQuery = graphql(`
  query SchemaList($datasource: String!, $refresh: Boolean) {
    schemaList(datasource: $datasource, refresh: $refresh) {
      defaultSchema listedAt source
      schemas { name scannedAt tables }
    }
  }
`)

export const StartSchemaScanMutation = graphql(`
  mutation StartSchemaScan($datasource: String!, $schemas: [String!]) {
    startSchemaScan(datasource: $datasource, schemas: $schemas) { id state error }
  }
`)

export const SchemaScanQuery = graphql(`
  query SchemaScan($id: ID!) {
    schemaScan(id: $id) { id state error }
  }
`)

export const CancelSchemaScanMutation = graphql(`
  mutation CancelSchemaScan($id: ID!) { cancelSchemaScan(id: $id) { id state } }
`)

export const TableCommentsQuery = graphql(`
  query TableComments($tables: [TableRef!]!) {
    tableComments(tables: $tables) { description columns { name description } }
  }
`)

export const ValidateQuery = graphql(`
  query Validate($draft: DraftInput!) { validate(draft: $draft) { ok error contentHash restartRequired warnings } }
`)

export const CapabilitiesQuery = graphql(`
  query Capabilities { capabilities { entity action privilege connection columns reason } }
`)

export const DiffQuery = graphql(`
  query Diff($from: ID!, $to: ID, $draft: DraftInput) { diff(from: $from, to: $to, draft: $draft) }
`)

export const SimulateQuery = graphql(`
  query Simulate($input: SimulationInput!) {
    simulate(input: $input) { allowed reason fields rowFilter grants fieldScopes }
  }
`)

export const VisibilityQuery = graphql(`
  query Visibility($input: VisibilityInput!) {
    visibility(input: $input) {
      entity
      actions { action result { allowed reason fields rowFilter grants fieldScopes } }
    }
  }
`)

export const CreateDraftMutation = graphql(`
  mutation CreateDraft($draft: DraftInput!, $comment: String) {
    createDraft(draft: $draft, comment: $comment) { ...RevisionParts }
  }
`)

export const PublishMutation = graphql(`
  mutation Publish($input: PublishInput!) {
    publish(input: $input) { ...RevisionParts }
  }
`)

export const RollbackMutation = graphql(`
  mutation Rollback($input: RollbackInput!) { rollback(input: $input) { ...RevisionParts } }
`)

export const GenerateUserTokenMutation = graphql(`
  mutation GenerateUserToken { generateUserToken { token tokenHash } }
`)

export const AdminAccountsQuery = graphql(`
  query AdminAccounts { adminAccounts { username permissions disabled createdAt updatedAt } }
`)

export const CreateAdminAccountMutation = graphql(`
  mutation CreateAdminAccount($input: AdminAccountInput!) { createAdminAccount(input: $input) { username } }
`)

export const UpdateAdminAccountMutation = graphql(`
  mutation UpdateAdminAccount($input: AdminAccountUpdate!) {
    updateAdminAccount(input: $input) { username permissions disabled }
  }
`)

export const SetAdminPasswordMutation = graphql(`
  mutation SetAdminPassword($input: SetAdminPasswordInput!) { setAdminPassword(input: $input) { username } }
`)

// Planning (planning.graphqls): the scanned catalog of every datasource,
// searched a page at a time on the server, and plans evaluated over it.
export const CatalogRowPartsFragment = graphql(`
  fragment CatalogRowParts on CatalogRow {
    ref datasource schema table description view columns foreignKeys referencedBy hasKey sideEffects status
    entity added missing scannedAt
  }
`)

export const CatalogQuery = graphql(`
  query Catalog($input: CatalogInput!) {
    catalog(input: $input) {
      total
      counts { all new workspace published drift }
      coverage { datasource scanned listed unscanned oldestScan }
      tables { ...CatalogRowParts }
    }
  }
`)

export const CatalogRefsQuery = graphql(`
  query CatalogRefs($filter: CatalogFilter!, $draft: DraftInput) { catalogRefs(filter: $filter, draft: $draft) }
`)

export const CatalogTableQuery = graphql(`
  query CatalogTable($ref: String!, $draft: DraftInput) {
    catalogTable(ref: $ref, draft: $draft) { ...ImportTableParts }
  }
`)

export const CatalogLinksQuery = graphql(`
  query CatalogLinks($ref: String!, $draft: DraftInput) {
    catalogLinks(ref: $ref, draft: $draft) {
      outgoing { ref name columns refColumns entity }
      incoming { ref name columns refColumns entity }
    }
  }
`)

export const PlanScopeQuery = graphql(`
  query PlanScope($scope: JSON!, $draft: DraftInput) {
    planScope(scope: $scope, draft: $draft) {
      total samples { ...CatalogRowParts } conditions { name value matched }
    }
  }
`)

export const PlanReportPartsFragment = graphql(`
  fragment PlanReportParts on PlanReport {
    matched excluded scannedFrom scannedTo
    objects { datasource schema tables imported changed }
    changes { kind principal actions mask fields entities }
    exceptions { kind level warning ref entity detail }
    unscanned { datasource schemas }
  }
`)

export const PreviewPlanQuery = graphql(`
  query PreviewPlan($plan: JSON!, $draft: DraftInput, $review: Boolean) {
    previewPlan(input: { plan: $plan, draft: $draft, review: $review }) {
      planId
      report { ...PlanReportParts }
      added
      entities { ...EntityParts }
      roles { name description grants { ...GrantParts } }
      users { name grants { ...GrantParts } }
      validation { ok error restartRequired warnings }
    }
  }
`)

export const PlanTemplatePartsFragment = graphql(`
  fragment PlanTemplateParts on PlanTemplate { name plan recurring version author updatedAt }
`)

export const PlanTemplatesQuery = graphql(`
  query PlanTemplates { planTemplates { ...PlanTemplateParts } }
`)

export const PlanTemplateVersionsQuery = graphql(`
  query PlanTemplateVersions($name: String!) { planTemplateVersions(name: $name) { ...PlanTemplateParts } }
`)

export const SavePlanTemplateMutation = graphql(`
  mutation SavePlanTemplate($input: PlanTemplateInput!) { savePlanTemplate(input: $input) { ...PlanTemplateParts } }
`)

export const DeletePlanTemplateMutation = graphql(`
  mutation DeletePlanTemplate($name: String!) { deletePlanTemplate(name: $name) }
`)

export const PendingStatePartsFragment = graphql(`
  fragment PendingStateParts on PendingState { key status owner reason until updatedBy updatedAt }
`)

export const PendingQuery = graphql(`
  query Pending($draft: DraftInput) {
    pending(draft: $draft) {
      drift newTables unscannedSchemas unlistedDatasources
      plans { key template { ...PlanTemplateParts } report { ...PlanReportParts } state { ...PendingStateParts } }
      driftTables { key ref entity added missing state { ...PendingStateParts } }
    }
  }
`)

export const PendingLogQuery = graphql(`
  query PendingLog($key: String!) { pendingLog(key: $key) { ...PendingStateParts } }
`)

export const SetPendingStateMutation = graphql(`
  mutation SetPendingState($input: PendingStateInput!) { setPendingState(input: $input) { ...PendingStateParts } }
`)

export const McpTokensQuery = graphql(`
  query McpTokens { mcpTokens { id name createdAt expiresAt lastUsedAt } }
`)

export const CreateMcpTokenMutation = graphql(`
  mutation CreateMcpToken($input: McpTokenInput!) {
    createMcpToken(input: $input) { token info { id name createdAt expiresAt lastUsedAt } }
  }
`)

export const RevokeMcpTokenMutation = graphql(`
  mutation RevokeMcpToken($id: ID!) { revokeMcpToken(id: $id) }
`)

export const ScanBatchPartsFragment = graphql(`
  fragment ScanBatchParts on ScanBatch {
    id datasource state total done failed canceled pending startedBy startedAt finishedAt
    items { schema state error }
  }
`)

export const ScanBatchesQuery = graphql(`
  query ScanBatches($datasource: String!) { scanBatches(datasource: $datasource) { ...ScanBatchParts } }
`)

export const StartScanBatchMutation = graphql(`
  mutation StartScanBatch($input: ScanBatchInput!) { startScanBatch(input: $input) { ...ScanBatchParts } }
`)

export const CancelScanBatchMutation = graphql(`
  mutation CancelScanBatch($id: ID!) { cancelScanBatch(id: $id) { ...ScanBatchParts } }
`)

export const RetryScanBatchMutation = graphql(`
  mutation RetryScanBatch($id: ID!) { retryScanBatch(id: $id) { ...ScanBatchParts } }
`)
